-- Governed starter catalogue. Templates create drafts only and never approve,
-- deploy, execute tools or create provider credentials.
SET NAMES utf8mb4;
SET time_zone = '+00:00';

ON DUPLICATE KEY UPDATE name=VALUES(name),department=VALUES(department),summary=VALUES(summary),risk_level=VALUES(risk_level),autonomy_level=VALUES(autonomy_level),configuration_json=VALUES(configuration_json),status=VALUES(status),updated_at=UTC_TIMESTAMP();
